# Variables: [Vm(nbus), Va(nbus), Pg(ngen), Qg(ngen)]
nvar = 2 * nbus + 2 * ngen

def unpack(x):
    return x[:nbus], x[nbus:2*nbus], x[2*nbus:2*nbus+ngen], x[2*nbus+ngen:]

def objective(x):
    Pg = x[2*nbus:2*nbus+ngen] * baseMVA
    return np.sum(cost_c2 * Pg**2 + cost_c1 * Pg + cost_c0)

def power_balance(x):
    Vm, Va, Pg, Qg = unpack(x)
    V = Vm * np.exp(1j * Va)
    S_inj = V * np.conj(Ybus @ V)
    Pg_bus = np.zeros(nbus)
    Qg_bus = np.zeros(nbus)
    for g in range(ngen):
        if gen_status[g] == 1:
            bi = bus_idx[gen_bus[g]]
            Pg_bus[bi] += Pg[g]
            Qg_bus[bi] += Qg[g]
    P_mis = Pg_bus - Pd - np.real(S_inj)
    Q_mis = Qg_bus - Qd - np.imag(S_inj)
    return np.concatenate([P_mis, Q_mis])
